#include <iostream>
using namespace std;

/*------------------------------------------------------
   函式宣告（Prototype）
   讓編譯器先知道 power() 是什麼，
   這樣 main() 在呼叫時就不會報錯。
------------------------------------------------------*/
double power(double x, int n);

int main()
{
    double sum = 0.0;   // 用來累加總和

    /*--------------------------------------------------
       計算題目級數：
       1/2 + 1/2^2 + 1/2^3 + ... + 1/2^10
       迴圈從 k=1 跑到 k=10
       每次都加上 1 / power(2.0, k)
    --------------------------------------------------*/
    for (int k = 1; k <= 10; k++) {
        sum += 1.0 / power(2.0, k);  // 呼叫 power 計算 2^k
    }

    // 輸出結果
    cout << "級數和 = " << sum << endl;
}


/*------------------------------------------------------
   第 8 題函式：計算 x^n（x 的 n 次方）
   x → 底數（double）
   n → 次方（int）
   回傳 double 結果
------------------------------------------------------*/
double power(double x, int n) {
    double result = 1.0;   // 次方運算從 1 開始（乘法單位元）

    /*--------------------------------------------------
       迴圈跑 n 次，每次乘上 x
       若 n = 3：
       第 1 次：result = x
       第 2 次：result = x^2
       第 3 次：result = x^3
    --------------------------------------------------*/
    for (int i = 0; i < n; i++) {
        result *= x;       // result = result * x
    }

    return result;         // 回傳 x^n
}
